-- QuizVerse SQLite Dump
-- Ready for SQLite environments

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS "migrations";
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);

DROP TABLE IF EXISTS "users";
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar not null default 'player', "xp" integer not null default '0', "level" integer not null default '1', "streak" integer not null default '0', "coins" integer not null default '100', "avatar" varchar, "bio" text, "is_banned" tinyint(1) not null default '0', "last_active_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "password_reset_tokens";
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

DROP TABLE IF EXISTS "sessions";
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));

DROP TABLE IF EXISTS "cache";
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "cache_locks";
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "jobs";
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

DROP TABLE IF EXISTS "job_batches";
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));

DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

DROP TABLE IF EXISTS "categories";
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "icon" varchar not null, "color_theme" varchar not null default 'violet', "bg_gradient" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "image" varchar);

DROP TABLE IF EXISTS "quizzes";
CREATE TABLE "quizzes" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "description" text, "category_id" integer not null, "user_id" integer not null, "difficulty" varchar not null default 'medium', "time_limit_per_question" integer not null default '20', "xp_reward" integer not null default '150', "is_published" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "plays_count" integer not null default '0', "rating" numeric not null default '4.85', "created_at" datetime, "updated_at" datetime, "question" text, "options" text, "correct_answer" varchar, "image" varchar, foreign key("category_id") references "categories"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);

DROP TABLE IF EXISTS "questions";
CREATE TABLE "questions" ("id" integer primary key autoincrement not null, "category_id" integer not null, "user_id" integer not null, "quiz_id" integer, "question_text" text not null, "question_type" varchar not null default 'multiple_choice', "explanation" text, "points" integer not null default '20', "difficulty" varchar not null default 'medium', "created_at" datetime, "updated_at" datetime, foreign key("category_id") references "categories"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("quiz_id") references "quizzes"("id") on delete set null);

DROP TABLE IF EXISTS "question_options";
CREATE TABLE "question_options" ("id" integer primary key autoincrement not null, "question_id" integer not null, "option_text" text not null, "is_correct" tinyint(1) not null default '0', "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("question_id") references "questions"("id") on delete cascade);

DROP TABLE IF EXISTS "quiz_attempts";
CREATE TABLE "quiz_attempts" ("id" integer primary key autoincrement not null, "user_id" integer not null, "quiz_id" integer, "mode" varchar not null default 'standard', "score" integer not null default '0', "total_questions" integer not null default '0', "correct_answers" integer not null default '0', "xp_earned" integer not null default '0', "accuracy_percentage" numeric not null default '0', "time_taken_seconds" integer not null default '0', "streak_count" integer not null default '0', "answers_summary" text, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("quiz_id") references "quizzes"("id") on delete set null);

DROP TABLE IF EXISTS "platform_settings";
CREATE TABLE "platform_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "type" varchar not null default 'string', "group" varchar not null default 'general', "label" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "audit_logs";
CREATE TABLE "audit_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "severity" varchar not null default 'info', "entity_type" varchar, "entity_id" integer, "details" text, "ip_address" varchar, "user_agent" text, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS "campaigns";
CREATE TABLE "campaigns" ("id" integer primary key autoincrement not null, "title" varchar not null, "type" varchar not null default 'banner', "status" varchar not null default 'active', "badge_text" varchar, "cta_text" varchar not null default 'Learn More', "target_url" varchar not null default '#', "content" text, "impressions" integer not null default '0', "clicks" integer not null default '0', "start_date" date, "end_date" date, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "roles";
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "permissions" text, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "staff_members";
CREATE TABLE "staff_members" ("id" integer primary key autoincrement not null, "user_id" integer not null, "role_id" integer not null, "department" varchar not null default 'Operations', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade);

COMMIT;
